CREATE TABLE "users" ("id" serial PRIMARY KEY,"name" varchar(255) NOT NULL,"email" varchar(255) NOT NULL,"password" varchar(255) NOT NULL,"role" varchar(20) NOT NULL DEFAULT 'worker',"is_active" boolean NOT NULL DEFAULT true,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX "users_email_unique" ON "users"("email");
CREATE TABLE "categories" ("id" serial PRIMARY KEY,"name" varchar(255) NOT NULL,"image" text,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "products" ("id" serial PRIMARY KEY,"category_id" integer REFERENCES "categories"("id") ON DELETE SET NULL,"name" varchar(255) NOT NULL,"purchase_price" numeric(12,2) NOT NULL DEFAULT 0,"sale_price" numeric(12,2) NOT NULL,"stock" integer NOT NULL DEFAULT 0 CHECK (stock >= 0),"min_stock" integer NOT NULL DEFAULT 0 CHECK (min_stock >= 0),"image" text,"is_active" boolean NOT NULL DEFAULT true,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "sales" ("id" serial PRIMARY KEY,"user_id" integer NOT NULL REFERENCES "users"("id"),"payment_method" varchar(50) NOT NULL DEFAULT 'cash',"note" text,"total" numeric(12,2) NOT NULL DEFAULT 0,"profit" numeric(12,2) NOT NULL DEFAULT 0,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "sale_items" ("id" serial PRIMARY KEY,"sale_id" integer NOT NULL REFERENCES "sales"("id") ON DELETE CASCADE,"product_id" integer NOT NULL REFERENCES "products"("id"),"quantity" integer NOT NULL CHECK (quantity > 0),"unit_price" numeric(12,2) NOT NULL,"purchase_price" numeric(12,2) NOT NULL DEFAULT 0,"total" numeric(12,2) NOT NULL,"profit" numeric(12,2) NOT NULL,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "stock_movements" ("id" serial PRIMARY KEY,"product_id" integer NOT NULL REFERENCES "products"("id"),"user_id" integer NOT NULL REFERENCES "users"("id"),"type" varchar(30) NOT NULL,"quantity" integer NOT NULL CHECK (quantity >= 0),"before_stock" integer NOT NULL,"after_stock" integer NOT NULL CHECK (after_stock >= 0),"note" text,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "settings" ("id" serial PRIMARY KEY,"key" varchar(255) NOT NULL,"value" text,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX "settings_key_unique" ON "settings"("key");
CREATE TABLE "refresh_tokens" ("id" serial PRIMARY KEY,"user_id" integer NOT NULL REFERENCES "users"("id") ON DELETE CASCADE,"token_hash" varchar(64) NOT NULL,"expires_at" timestamptz NOT NULL,"revoked_at" timestamptz,"created_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX "refresh_token_hash_unique" ON "refresh_tokens"("token_hash");
